def search(x, seq):
    for i in range(len(seq)):
        if x <= seq[i]:
            return i
    return i + 1

def factorial(n):
    if n < 0:
        return 0
    fact = 1
    for i in range(n):
        fact = fact * (i + 1)
    return fact

def frequency_lists(list1):
    list1 = [item for sublist in list1 for item in sublist]
    dic_data = {}
