def transpose_array(b):
    n = len(b)
    for i in range(n):
        for j in range(i, n):
            b[i][j], b[j][i] = b[j][i], b[i][j]
    return b

def evolve_pokemon(pokemon, current_level):
    evolution_dict = {
        "Bulbasaur": ("Ivysaur", "Venusaur"),
        "Charmander": ("Charmeleon", "Charizard"),
        "Squirtle": ("Wartortle", "Blastoise")
    }
    root_pokemon = pokemon
    pokemon_found = False
    if pokemon not in evolution_dict:
        # check if pokemon is in any of the evolution paths
        for key, value in evolution_dict.items():
            if pokemon in value:
                pokemon_found = True
                root_pokemon = key
                break
        if not pokemon_found:
            return None
    if root_pokemon in evolution_dict or pokemon_found:
        evolution_levels = [i * 16 for i in range(1, len(evolution_dict[root_pokemon]) + 1)]
        if current_level < evolution_levels[0]:
            return root_pokemon

        # Check each evolution threshold
        for i in range(len(evolution_levels)):
            if current_level < evolution_levels[i]:
                return evolution_dict[root_pokemon][i-1]

        # If level meets all thresholds, return final evolution
        return evolution_dict[root_pokemon][-1]

def is_magic_square(square):
    n = len(square)
    expected_sum = n * (n ** 2 + 1) // 2
    for i in range(n):
        row_sum = sum(square[i])
        if row_sum != expected_sum:
            return False

    for j in range(n):
        col_sum = sum(square[i][j] for i in range(n))
        if col_sum != expected_sum:
            return False

    diagonal_sum = sum(square[i][i] for i in range(n))
    if diagonal_sum != expected_sum:
        return False

    diagonal_sum = sum(square[i][n - i - 1] for i in range(n))
    if diagonal_sum != expected_sum:
        return False

    return True

